// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    address admin;

    function setUp() public {
        admin = msg.sender;
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.prank(admin);
        c.grantRole(c.PROPOSER_ROLE(), actor);
        assertTrue(
            !c.hasRole(c.PROPOSER_ROLE(), actor) || c.getRoleAdmin(c.PROPOSER_ROLE()) != bytes32(0),
            "admin of a granted role must be nonzero"
        );
    }
}
